import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;

import static org.junit.jupiter.api.Assertions.*;

class FindEnclosingAttributeTests {

    @Test
    void testFindEnclosingAttributeWithMatchingAttribute() throws Exception {
        Document document = createSampleDocument();
        Node childNode = document.getElementsByTagName("child").item(0);

        String result = findEnclosingAttribute(childNode, "attr");
        assertEquals("value", result);
    }

    @Test
    void testFindEnclosingAttributeWithNoMatchingAttribute() throws Exception {
        Document document = createSampleDocument();
        Node childNode = document.getElementsByTagName("child").item(0);

        String result = findEnclosingAttribute(childNode, "nonexistent");
        assertNull(result);
    }

    @Test
    void testFindEnclosingAttributeWithNullNode() {
        String result = findEnclosingAttribute(null, "attr");
        assertNull(result);
    }

    @Test
    void testFindEnclosingAttributeWithEmptyAttributeName() throws Exception {
        Document document = createSampleDocument();
        Node childNode = document.getElementsByTagName("child").item(0);

        String result = findEnclosingAttribute(childNode, "");
        assertNull(result);
    }

    @Test
    void testFindEnclosingAttributeWithParentHavingAttribute() throws Exception {
        Document document = createSampleDocument();
        Node grandChildNode = document.getElementsByTagName("grandchild").item(0);

        String result = findEnclosingAttribute(grandChildNode, "attr");
        assertEquals("value", result);
    }

    private Document createSampleDocument() throws Exception {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document document = builder.newDocument();

        Element root = document.createElement("root");
        document.appendChild(root);

        Element child = document.createElement("child");
        child.setAttribute("attr", "value");
        root.appendChild(child);

        Element grandChild = document.createElement("grandchild");
        child.appendChild(grandChild);

        return document;
    }

    private String findEnclosingAttribute(Node n, String attrName) {
        while (n != null) {
            if (n.getNodeType() == Node.ELEMENT_NODE) {
                final Element e = (Element) n;
                final String attr = e.getAttribute(attrName);
                if (attr != null && !attr.isEmpty()) {
                    return attr;
                }
            }
            n = n.getParentNode();
        }
        return null;
    }
}

