    }

    @Test
    void testFindFactoryFromJavaHomePropertiesFile() throws IOException {
        createJavaHomePropertiesFile(TEST_PROPERTY, "java.home.factory");
        String result = invokeFindFactory(TEST_PROPERTY, DEFAULT_FACTORY);
        assertEquals("java.home.factory", result);
        deleteJavaHomePropertiesFile();
    }

    @Test
    void testFindFactoryFromMetaInfServices() throws IOException {
        createMetaInfServiceFile(TEST_PROPERTY, "meta.inf.factory");
        String result = invokeFindFactory(TEST_PROPERTY, DEFAULT_FACTORY);
