        String result = invokeFindFactory(TEST_PROPERTY, DEFAULT_FACTORY);
        assertEquals(DEFAULT_FACTORY, result);
    }

    @Test
    void testFindFactoryHandlesIOExceptionGracefully() throws IOException {
        createJavaHomePropertiesFile(TEST_PROPERTY, "java.home.factory");
        Path configFilePath = Paths.get(CONFIG_FILE_PATH);
        try (FileOutputStream fos = new FileOutputStream(configFilePath.toFile())) {
            fos.getChannel().lock(); // Lock the file to simulate IOException
